package shell

import "strings"

// Active reports whether href is the current page or a parent of it
// (REQ-CNT-06). The sidebar marks active items on the server.
func Active(path string, href string) bool {
	if href == "" || path == "" {
		return false
	}
	if path == href {
		return true
	}
	return len(path) > len(href) && path[:len(href)] == href && path[len(href)-1] == '/'
}

// ActiveItem reports whether any descendant of item is active.
func ActiveItem(path string, item NavItem) bool {
	if Active(path, string(item.Href)) {
		return true
	}
	for _, child := range item.Items {
		if ActiveItem(path, child) {
			return true
		}
	}
	return false
}

// HasTOC reports whether the page has headings to show.
func (p Page) HasTOC() bool {
	for _, h := range p.TOC {
		if h.Text != "" {
			return true
		}
	}
	return false
}

// TocDepth returns the heading depth limit of the page.
func (p Page) TocDepth() int {
	if p.Depth <= 0 {
		return 3
	}
	return p.Depth
}

// ShownTOC returns the headings the table of contents shows.
func (p Page) ShownTOC() []Heading {
	depth := p.TocDepth()
	var out []Heading
	for _, h := range p.TOC {
		if h.Level >= 2 && h.Level <= depth && h.Text != "" {
			out = append(out, h)
		}
	}
	return out
}

// EditURL returns the edit-page link of the page (REQ-CNT-06). The page
// path maps to its Markdown file: "/start/" to "start.md".
func (c Config) EditURL(p Page) string {
	if c.EditBase == "" || p.Path == "" {
		return ""
	}
	base := c.EditBase
	if base[len(base)-1] != '/' {
		base += "/"
	}
	path := strings.TrimPrefix(p.Path, "/")
	path = strings.TrimSuffix(path, "/")
	if path == "" {
		path = "index"
	}
	return base + path + ".md"
}

// Package shell is the docs-shell registry block (REQ-CNT-06): a layout
// with a header, a sidebar, a table of contents, pagination and a 404, plus
// the client behaviours they need.
package shell

import "github.com/alternayte/gx"

// Nav is the sidebar model (REQ-CNT-06).
type Nav struct {
	Groups []NavGroup
}

// NavGroup is one sidebar section. A group with Collapsed starts closed.
type NavGroup struct {
	Label     string
	Badge     string
	Collapsed bool
	Items     []NavItem
}

// NavItem is one sidebar link. Items nest under a parent item.
type NavItem struct {
	Label string
	Href  gx.URL
	Badge string
	Items []NavItem
}

// Link is one header link: a social link or a plain link.
type Link struct {
	Label string
	Href  gx.URL
}

// Config is the site-wide shell data (REQ-CNT-06).
type Config struct {
	Title   string
	Version string
	Links   []Link
	// EditBase is the repository edit URL up to the file path, for example
	// https://github.com/acme/site/edit/main/content/docs/. Empty hides
	// the edit link.
	EditBase string
}

// Page is the shell data of one page (REQ-CNT-06).
type Page struct {
	Title string
	// Path is the site path of the page, for example /start/.
	Path string
	// Section is the sidebar group label of the page.
	Section string
	// Updated is the last-updated text. Empty hides it.
	Updated string
	// Prev and Next are the previous and next sidebar items.
	Prev *NavItem
	Next *NavItem
	// TOC holds the page headings, in document order.
	TOC []Heading
	// Depth limits the table of contents to headings at or below this
	// level. Zero means 3.
	Depth int
}

// Heading is one table-of-contents entry (REQ-CNT-06).
type Heading struct {
	Level int
	Text  string
	ID    string
}
